#include <iostream>
#include <ctime>
#include <cstdlib>

#define DECK 5
#define CARD_COUNT 20

using std::cout;
using std::endl;

int main()
{
    srand(time(NULL));

    int iCards[CARD_COUNT];
    for (int i = 0; i < CARD_COUNT; i++)
    {
        iCards[i] = i;
    }

    // Fisher-Yates Shuffle
    for (int i = CARD_COUNT - 1; i > 0; i--)
    {
        int j = rand() % (i + 1);

        int iTemp = iCards[i];
        iCards[i] = iCards[j];
        iCards[j] = iTemp;
    }

    int iPlayer[DECK] = {};
    int iDealer[DECK] = {};
    for (int i = 0; i < DECK; i++)
    {
        iPlayer[i] = iCards[i * 2];
        iDealer[i] = iCards[i * 2 + 1];
    }

    cout << "Player: ";
    for (int i = 0; i < DECK; i++)
        cout << iPlayer[i] << " ";
    cout << endl;

    cout << "Dealer: ";
    for (int i = 0; i < DECK; i++)
        cout << iDealer[i] << " ";
    cout << endl;

    return 0;
}

