#include <iostream>

#define DECK 5
#define RADIX 13

using std::cout;
using std::endl;

int main()
{
    int iHand[DECK] = { 37, 3, 25, 0, 51 };

    // Optimized Bubble Sort
    for (int i = 0; i < DECK - 1; i++)
    {
        bool bSwapped = false;

        for (int j = 0; j < DECK - 1 - i; j++)
        {
            if (iHand[j] > iHand[j + 1])
            {
                int iTemp = iHand[j];
                iHand[j] = iHand[j + 1];
                iHand[j + 1] = iTemp;

                bSwapped = true;
            }
        }

        if (!bSwapped)
            break;
    }

    // Rendering
    for (int i = 0; i < DECK; i++)
    {
        switch (iHand[i] / RADIX)
        {
        case 0: cout << "SPADE ";   break;
        case 1: cout << "DIAMOND "; break;
        case 2: cout << "HEART ";   break;
        case 3: cout << "CLOVER ";  break;
        }

        switch (iHand[i] % RADIX)
        {
        case 0:  cout << "A";  break;
        case 10: cout << "J";  break;
        case 11: cout << "Q";  break;
        case 12: cout << "K";  break;
        default: cout << iHand[i] % RADIX + 1; break;
        }

        cout << "\t";
    }
    cout << endl;

    return 0;
}
